def choose_move(observation):
    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)
    pos = observation.get("self_position", (0, 0))
    opp = observation.get("opponent_position", (0, 0))
    resources = observation.get("resources", [])
    obstacles = observation.get("obstacles", [])
    remaining = observation.get("remaining_resource_count", 0)
    # simple deterministic heuristic: try to move toward nearest resource; avoid opponent by shifting away if close
    x, y = pos
    ox, oy = opp
    best = [-1, 0, 0]  # [score, dx, dy]

    def score_move(dx, dy):
        nx, ny = x + dx, y + dy
        if nx < 0 or ny < 0 or nx >= grid_w or ny >= grid_h:
            return -9999
        if (nx, ny) in obstacles:
            return -999
        dist_to_opp = (nx - ox) ** 2 + (ny - oy) ** 2
        dist_to_res = None
        for r in resources:
            rx, ry = r.get("x", 0), r.get("y", 0)
            if dist_to_res is None:
                dist_to_res = (rx - nx) ** 2 + (ry - ny) ** 2
            else:
                d = (rx - nx) ** 2 + (ry - ny) ** 2
                if d < dist_to_res:
                    dist_to_res = d
        s = 0
        if dist_to_opp < 4:
            s -= 4  # deter from being too close to opponent
        if dist_to_res is not None:
            s += max(0, 5 - (dist_to_res // 2))
        return s

    # Try all 9 moves (including stay)
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            if dx == 0 and dy == 0:
                m = score_move(0, 0)
                if m > best[0]:
                    best = [m, 0, 0]
            else:
                m = score_move(dx, dy)
                if m > best[0]:
                    best = [m, dx, dy]

    return [best[1], best[2]]
